head.script:
scwin.input1_onkeyup = function(e) {
    if (WebSquare.util.isChrome() || WebSquare.util.isSafari()) {
        var val = input1.getValue();
        var charcode = val.charCodeAt(val.length - 1);
        if (charcode > 10000) {
            //console.log("before = " + val);
            input1.setValue(val.substring(0, val.length - 1));
            //console.log("after = " + input1.getValue());
        }
    }
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate = function() {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    // Test step 1.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.simulateWrapper('#'+$p.id+'wq_uuid_1', 'key-sequence', {sequence: '111'})");
    // Test step 1.
    //1.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_1').css('background-color') == 'rgb(237, 243, 251)'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Created By: park
    //Created By: 28-june-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
